<?php require dirname(__DIR__).'/inc/page_helpers.php';login_required();if(page_post()){check_csrf();$t=trim((string)($_POST['title']??''));$b=trim((string)($_POST['body']??''));if($t!==''&&$b!==''){$db->beginTransaction();try{$q=$db->prepare('INSERT INTO forum_topics(user_id,title) VALUES(?,?)');$q->execute([$currentUser['id'],$t]);$id=(int)$db->lastInsertId();$db->prepare('INSERT INTO forum_replies(topic_id,user_id,body) VALUES(?,?,?)')->execute([$id,$currentUser['id'],$b]);$db->commit();go('/Forum/ShowPost.php?id='.$id);}catch(Throwable $e){$db->rollBack();throw $e;}}notice('Title and message are required.','error');}page_start('Create Topic');?><section class="Panel"><h1>Create topic</h1><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Title<input name="title" maxlength="120" required></label><label>Message<textarea name="body" required></textarea></label><button class="Button">Post</button></form></section><?php page_end();